private void loadFromIntent() {
  if (null != getIntent() && null != getIntent().getExtras()) {
    FILE_PATH = getIntent().getExtras().getString("filepath");
    if (!TextUtils.isEmpty(FILE_PATH)) {
      try {
        Glide.with(this).load(new File(FILE_PATH)).into(imageView);
        return;
      } catch (FileNotFoundException | IOException e) {
        // Handle the exception, e.g., log the error or show a message to the user
        e.printStackTrace();
      }
    }
  }
  SnackBarHandler.show(parent, R.string.image_invalid);
}
